insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:horticulturist','AU','horticulturist','Horticulturist (multi-occupation umbrella)','OSCA','2024 v1.0','34','AUD',false,'TRA assesses the representative Nurseryperson 362411 migration path; no universal occupational registration','https://www.tradesrecognitionaustralia.gov.au/','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:horticulturist','2026-05-01',null,null,null,null,1852,null,null,null,null,46.33333,'2026-05-01',-27.98,2.70,8.79,0,0,5,0,15,0,5,5,5,30,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','No single current OSCA Horticulturist occupation exists. Relevant work is split across 342931 Nurseryperson, 343134 Horticultural Supervisor or Specialist, and production-growing occupations.','representative_proxy','OSCA 342931 Nurseryperson / ANZSCO 362411 is used only as a representative nursery-focused migration path.','labour_scope','Generic Horticulturist employment and earnings remain null. Broader ANZSCO 3624 has 4,400 workers, 63% part-time share, 45% female share, median age 59 and median hourly earnings of 35 AUD, but these are context only.','vacancy_scope','Broader 3624 vacancies were 46.33333 in May 2026 versus 64.33333 in May 2025, about -27.98% year on year; no exact intensity or trend credit.','projection_scope','Broader 3624 projections are +2.70% to 2030 and +8.79% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records both current Nurseryperson 342931 and Horticultural Supervisor or Specialist 343134 as No Shortage nationally.','visa_basis','The current CSOL includes Nurseryperson 362411 with TRA, but that path applies only to nursery-focused horticulture; partial visa credit only.','entry_level_basis','TAFE SA Certificate III in Horticulture 117361C explicitly lists Horticulturist as a possible outcome; ECU Master of Horticultural Science 108845B is a current postgraduate specialist route.','score_note','The model avoids manufacturing a generic labour total and preserves the split between trade, specialist and production horticulture roles.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
